var ResourceActions = []string{"abstraction.credentials/holder.manage", "abstraction.credentials/holder.read", "abstraction.credentials/apply"}

var ExecutionGuarantees = []string{"abstraction.download/credentials@1"}

var Consumers = []string{"abstraction.download/http-execution@1", "abstraction.model/resolver@1", "abstraction.inference/chat@1"}

// Account identifier and normalized absolute executable path, the same shape as
// abstraction.rights Subject. It is an assertion by the party that bound native
// Program proof: the holder for registered_by and audit entries of holder
// calls, the designated enforcer for Use.subject. It contains no proof.
type Subject struct {
	Account string
	Program string
}

// targets: 1..16 lowercase host names, each covering itself and its subdomains;
// no scheme, port, path or wildcard characters. consumers: 1..8 wire contract
// names of services that may apply the credential. Both lists are exact; a host
// or contract outside them is refused at Apply.
type Scope struct {
	Targets   []string
	Consumers []string
}

// Metadata only. registered_by is the subject the receiving boundary bound from
// native Program proof when the record was stored, asserted by the holder; it
// is provenance and carries no proof. No field derives from the secret bytes:
// no length, hash, prefix or suffix. header is present exactly for kind header.
type Metadata struct {
	Name         string
	Kind         string
	Revision     string
	State        State
	Scope        Scope
	RegisteredBy Subject
	Registered   string
	Expires      string
	Header       string
	LastApplied  string
}

// name is 1..64 bytes of A-Z a-z 0-9 _ - . and unique within the receiving
// account. kind is a seed or <owner>/<name>@<n>. secret is
// 1..Limits.max_secret_bytes bytes with no control character other than tab,
// and is written only to the configured platform store; this document is never
// retained, logged or echoed. header is an HTTP field name, required for kind
// header and refused otherwise. expires, when present, is after the receiving
// clock.
type Registration struct {
	Name    string
	Kind    string
	Scope   Scope
	Expires string
	Header  string
	Secret  []byte
}

// Replacement bytes and expiry for an existing record. secret follows
// Registration.secret and is never retained, logged or echoed. Absent expires
// clears expiry; a present expires is after the receiving clock.
type Rotation struct {
	Name    string
	Expires string
	Secret  []byte
}

// stored carries the new revision and current metadata. conflict carries the
// revision and current metadata observed inside the conditional edit. Other
// outcomes carry an empty revision and no current. An empty expected revision
// requires that the name not exist; a tombstoned name conflicts until retention
// elapses. A stale expected revision conflicts even when the desired state
// already holds. A lost reply is uncertain: reconcile from current or List
// before another edit. no_secure_store means this runtime has no configured
// platform store, or is a machine-scope runtime; nothing was retained anywhere.
// exhausted means the account holds its maximum number of records.
type StoreResult struct {
	Outcome  StoreOutcome
	Revision string
	Current  *Metadata
}

// rotated carries the new revision; the previous bytes are destroyed once the
// new item is written, and an in-flight Apply uses the new bytes on its next
// request. A lost or expired record returns to active. conflict carries current
// metadata. A revoked record reads unknown.
type RotateResult struct {
	Outcome  RotateOutcome
	Revision string
	Current  *Metadata
}

// revoked destroys the bytes at once and keeps a tombstone for
// Limits.tombstone_retention_ms, during which Apply reads revoked; afterwards
// the name reads unknown and may be registered again. conflict carries the
// current revision. invalid is a malformed name or revision. A platform store
// that cannot destroy the bytes reads unavailable and the record is unchanged.
type RevokeResult struct {
	Outcome  RevokeOutcome
	Revision string
}

// Provider-declared bounds, read through List. max_secret_bytes is at most 4096
// and is lower where the configured store bounds it. secure_store names the
// configured store: SecureStore names this version's standard backends,
// provider extensions are retained, and refusal-page zero limits carry the
// empty word. supported_kinds are the kinds an applier on this runtime can
// apply; Store refuses any other.
type Limits struct {
	MaxCredentials       int64
	MaxSecretBytes       int64
	TombstoneRetentionMs int64
	AuditRetentionMs     int64
	AuditCapacity        int64
	SecureStore          SecureStore
	SupportedKinds       []string
}

// page carries 0..limit records of the receiving account in name order,
// including tombstones inside retention. Cursors are at most 256 bytes, bind
// receiving account and provider epoch, and return gap after restart or scope
// mismatch; restart from an empty cursor. A noncomplete page has a nonempty
// next. Refusals carry zero limits, no records, empty next and complete=false.
type MetadataPage struct {
	Outcome  PageOutcome
	Limits   Limits
	Records  []Metadata
	Next     string
	Complete bool
}

// One retained event in journal order. event is an open word: stored, rotated,
// revoked, expired, lost, retired, checked, applied, refused. subject is the
// asserted submitting or registering subject; consumer and target are present
// for checked, applied and refused; outcome is the exact holder or rights
// outcome word. Entries carry names and never values.
type AuditEntry struct {
	Sequence int64
	Time     string
	Event    string
	Name     string
	Revision string
	Subject  *Subject
	Consumer string
	Target   string
	Outcome  string
}

// page carries at most max_entries entries after the cursor. The journal
// retains Limits.audit_capacity entries for Limits.audit_retention_ms per
// account; a cursor older than the retained journal, or from another provider
// epoch, returns gap. Refusals carry no entries, an unchanged cursor and
// at_end=false.
type AuditPage struct {
	Outcome PageOutcome
	Entries []AuditEntry
	Next    string
	AtEnd   bool
}

// subject is the submitting caller as bound at the consuming service's own
// boundary and asserted by that authorized enforcer; serialization conveys no
// proof. consumer is the calling service's wire contract name: a consumers seed
// or <owner>/<name>@<n>. target is the lowercase host the request will open.
// challenge carries kind-specific input, for example a registry authenticate
// challenge, and is refused as invalid for the seed kinds.
type Use struct {
	Subject   Subject
	Consumer  string
	Name      string
	Target    string
	Challenge string
}

// applied means Apply with the same Use would carry headers now. revision is
// present for evaluated records. No secret is read for a check.
type CheckResult struct {
	Outcome  ApplyOutcome
	Revision string
}

// headers is present exactly for applied and holds the request headers for this
// one request: Authorization for bearer and challenge kinds, the registered
// header name for kind header. The consuming service sends them once, keeps
// them out of every record, log and reply, and calls Apply again for the next
// request, redirect or resumed range. Other outcomes carry no headers.
// not_permitted means the rights decision for subject,
// abstraction.credentials/apply and credential:<name> was anything except
// permitted; the exact word is in the audit trail. target_refused and
// consumer_refused name Scope mismatches. forbidden means the calling peer is
// not a designated enforcer, or the subject could not be bound on this
// platform. unavailable means the rights service or the platform store could
// not be reached; nothing was applied.
type ApplyResult struct {
	Outcome  ApplyOutcome
	Revision string
	Headers  map[string]string
}

